UPDATE  LAB_PHYSICAL_FACILITY set LAB_NAME =#{p_lab_name}, ADDRESS=#{p_address}, LAFT_STAFF = #{p_laftStaffAssigned}, CITY=#{p_city}, 
STATE=#{p_state}, ZIP=#{p_zip}, COUNTRY=#{p_country},  FLAG_ACTIVE=#{p_flag_active}, LAST_UPDATED_BY=#{p_lastUpdatedBy}, 
LAST_UPDATED_DATE= SYSDATE, FLAG_SERVES_NYC= #{p_flagServersNYC}, FLAG_BLOOD_BANK = #{p_flagBloodBank}, APPROVAL_STATUS_CODE=#{p_approvalStatusCode},
LOW_VOLUME=#{p_lowVolume}, PHY_OFF_LAB=#{p_physicianOfficeLab}, REFERS_DTA_TESTING_TO=#{p_refersDTATestingTo}, PERFORMS_DTA=#{p_performsDTA}
where PFI = #{p_pfi} and CLIA = #{p_clia}

UPDATE LAB_LOINC_MAPPING set   START_DATE = to_date(#{dateValidFrom}, 'MM/DD/YYYY'),  END_DATE =to_date(#{dateValidTill}, 'MM/DD/YYYY'), 
LAST_UPDATED_BY = #{lastUpdatedBy}, LAST_UPDATED_DATE = SYSDATE,  TEST_KIT = #{testKit}, INSTRUMENT = #{instrument}, VL_DETECTION_LEVEL = #{vlDetectionLevel} 
where LAB_LOINC_MAP_ID = #{loincMapId}

