select INTERACTION_ID interactionId, u.legacy_uid interactionBy, TO_CHAR(INTERACTION_DATE, 'MM/DD/YYYY') interactionDate, 
COMMUNICATION_TYPE communicationType, INTERACTION_NOTES interactionNotes
from LAB_INTERACTION_HISTORY lih join NYEHMS_USERS u on lih.INTERACTION_BY = u.worker_id where INTERACTION_ID = #{labInteractionId}

WITH loinc_data AS ( SELECT Distinct a.clia, a.pfi, a.lab_name facilityName, Nvl(a.flag_serves_nyc, 'N') nycLab, b.approval_status_desc apporvalStatus, a.laft_staff staffName, performs_dta performDTA, flag_blood_bank donorLab,a.address, a.city, a.state, a.zip, a.phy_off_lab phyofflab, pkg_trk_common.fn_get_fullname (u.last_name, u.first_name, u.middle_name, NULL) userName, COUNT(Distinct a.pfi) OVER (PARTITION BY 1) statusRecCt, COUNT(Distinct a.pfi) OVER (PARTITION BY b.approval_status_code) totalRecCt, c.description lab_submission_type, m.loinc_cd loinc, t.test_type testType, To_char(m.start_date, 'MM/DD/YYYY') testingStartDate, t.contact_name contactName, t.email contactEmail, t.phone contactPhone FROM lab_physical_facility a LEFT OUTER JOIN coded_lab_approval_status b ON (a.approval_status_code = b.approval_status_code) LEFT OUTER JOIN nyehms_users u ON (a.laft_staff = u.legacy_uid and u.end_date is null) LEFT OUTER JOIN lab_submission_type_mapping l ON l.pfi = a.pfi AND l.end_date IS NULL LEFT OUTER JOIN coded_lab_submission_type c ON c.submission_type_cd = l.submission_type_cd LEFT OUTER JOIN lab_loinc_mapping m ON m.pfi = a.pfi AND m.end_date IS NULL LEFT OUTER JOIN lab_loinc ll ON ll.loinc_cd = m.loinc_cd LEFT OUTER JOIN coded_lab_test_type t ON t.test_type_cd = ll.test_type_cd LEFT OUTER JOIN lab_alternative_contacts t ON t.pfi = a.pfi AND t.main_contact = 'Y' AND t.retired_date IS NULL WHERE a.pfi != '-999'
AND b.approval_status_code IN ( SELECT Trim(regexp_substr(#{approvalStatus}, '[^,]+', 1, level)) FROM dual CONNECT BY regexp_substr(#{approvalStatus}, '[^,]+', 1, level) IS NOT NULL )
) SELECT clia, pfi, facilityName, nyclab, apporvalstatus, staffname, performDTA, donorlab, address, city, state, zip, phyofflab, username, statusrecct, totalrecct, Listagg(lab_submission_type, ', ') WITHIN GROUP (ORDER BY loinc) rptFileType , loinc, testType, testingStartDate, contactName, contactEmail, contactPhone FROM loinc_data GROUP BY clia, pfi, facilityName, nyclab, apporvalstatus, staffname, performDTA, donorlab, address, city, state, zip, phyofflab, username, statusrecct, totalrecct, loinc, testType, testingStartDate, contactName, contactEmail, contactPhone ORDER BY pfi
